#include <cstdint>
volatile std::uint64_t benchmark_salt=1;
#include HEADER
#include <chrono>
#include <cstdlib>
#include <iostream>
#include <random>
#include <string>
#include <vector>
using Clock=std::chrono::steady_clock;
static volatile std::uint64_t sink=0;
template<bool Packed,unsigned D>int run(const std::string&mode,std::size_t n,int family,int reps){
 using Table=reinsirk::detail::InternalHashMap<std::uint64_t,std::uint64_t,Packed,D>;
 std::vector<std::uint64_t> keys(n);std::mt19937_64 rng(4372);
 for(std::size_t i=0;i<n;++i)keys[i]=family==0?rng():family==1?i:i*256;
 auto time=[&](auto operation){std::uint64_t checksum=0;const auto begin=Clock::now();for(int r=0;r<reps;++r){asm volatile("":::"memory");checksum+=operation();}sink=checksum;std::cout<<std::chrono::duration<double,std::milli>(Clock::now()-begin).count()<<' '<<checksum<<'\n';};
 if(mode=="build"||mode=="reserve_build"){
  time([&]{Table t;if(mode=="reserve_build")t.reserve(n);for(auto k:keys)t[k]=k+1;return t.size();});return 0;
 }
 Table t;if(mode=="sparse_miss")t.reserve(n*4);for(auto k:keys)t[k]=k+1;
 if(mode=="hit")time([&]{std::uint64_t sum=0;for(auto k:keys){const auto*p=t.find(k);if(p)sum+=*p;}return sum;});
 else if(mode=="subscript")time([&]{std::uint64_t sum=0;for(auto k:keys)sum+=t[k];return sum;});
 else if(mode=="emplace_hit")time([&]{std::uint64_t sum=0;for(auto k:keys)sum+=t.find_or_emplace(k,[]{return std::uint64_t{0};});return sum;});
 else if(mode=="miss"||mode=="sparse_miss")time([&]{std::uint64_t sum=0;for(auto k:keys)sum+=t.find(k^UINT64_C(0xd6751cb79a3e5601))==nullptr;return sum;});
 else if(mode=="reuse")time([&]{t.clear();for(auto k:keys)t[k]=k+1;return t.size();});
 else return 3;return 0;
}
int main(int argc,char**argv){if(argc!=8)return 2;std::string mode=argv[1];std::size_t n=std::strtoull(argv[2],nullptr,0);int family=std::atoi(argv[3]),packed=std::atoi(argv[4]),d=std::atoi(argv[5]),reps=std::atoi(argv[6]);benchmark_salt=std::strtoull(argv[7],nullptr,0);
 if(packed)return run<true,4>(mode,n,family,reps);
 if(d==2)return run<false,2>(mode,n,family,reps);
 if(d==8)return run<false,8>(mode,n,family,reps);
 return run<false,5>(mode,n,family,reps);
}

