from pathlib import Path
import fcntl,hashlib,json,math,random,statistics,subprocess
b=Path(__file__).resolve().parent
variants=['baseline','operator','combined','flagfirst'];salts=['0x9e3779b97f4a7c15','0xd6e8feb86659fd93','0xa0761d6478bd642f']
work=[]
def add(n,ops,f=0,p=0,d=5):
 for mode in ops.split():work.append({'name':f'{mode}_{n}_{f}_{p}_{d}','args':[mode,str(n),str(f),str(p),str(d),'1',salts[0]]})
add(32,'build subscript hit miss emplace_hit sparse_miss');add(1024,'build subscript hit miss emplace_hit sparse_miss')
add(200000,'build reserve_build subscript hit miss emplace_hit sparse_miss reuse');add(500000,'build subscript hit miss')
for f in [1,2]:add(200000,'subscript miss',f)
