for d in [2,8]:add(200000,'subscript miss',d=d)
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
data={'source_hashes':{v:sha(b/(v+'.hpp'))for v in variants},'fixed_hashes':{v:sha(b/(v+'_fixed.hpp'))for v in variants},'benchmark_sha256':sha(b/'bench.cpp'),'workloads':work,'salts':salts,'samples_per_salt':3,'cpu':20,'compile_cpu':22,'build':[],'rows':[],'summaries':{}}
def save():(b/'screen-results.json').write_text(json.dumps(data,indent=2)+'\n')
for cfg,compiler in [('gcc',['/usr/bin/g++']),('clang',['/usr/bin/clang++','--gcc-install-dir=/usr/lib/gcc/x86_64-linux-gnu/15'])]:
 for v in variants:
  cmd=['taskset','-c','22',*compiler,'-std=c++23','-O2','-DSKIP_RUNTIME_CHECKS','-DHEADER="'+str(b/(v+'_fixed.hpp'))+'"',str(b/'bench.cpp'),'-o',str(b/(cfg+'-'+v))];subprocess.run(cmd,check=True)
  data['build'].append({'config':cfg,'variant':v,'command':cmd,'sha256':sha(b/(cfg+'-'+v))})
 print('compiled',cfg,flush=True)
with open('/tmp/sirkit_internal_hash_cpu20.lock','w')as lock:
 fcntl.flock(lock,fcntl.LOCK_EX)
 for w in work:
  a=w['args'].copy();out=subprocess.check_output(['taskset','-c','20',str(b/'gcc-baseline'),*a],text=True).split();ms=float(out[0]);a[5]=str(max(1,min(10000000,math.ceil(15/max(ms,.000001)))))
  ms=float(subprocess.check_output(['taskset','-c','20',str(b/'gcc-baseline'),*a],text=True).split()[0]);a[5]=str(max(1,min(10000000,math.ceil(int(a[5])*15/max(ms,.000001)))))
  w['args']=a;w['repetitions']=int(a[5])
 save();print('calibrated',len(work),flush=True)
 for cfg in ['gcc','clang']:
  for wi,w in enumerate(work):
   for si,salt in enumerate(salts):
    a=w['args'].copy();a[6]=salt
    for rep in range(3):
     order=variants.copy();random.Random(wi*73+si*17+rep).shuffle(order);checks=set()
     for v in order:
      out=subprocess.check_output(['taskset','-c','20',str(b/(cfg+'-'+v)),*a],text=True).split();checks.add(out[1]);data['rows'].append({'config':cfg,'case':w['name'],'salt':salt,'rep':rep,'variant':v,'ms':float(out[0]),'checksum':out[1]})
     assert len(checks)==1,(cfg,w['name'],salt,checks)
  summary={}
  for w in work:
   med={v:statistics.median(x['ms']for x in data['rows']if x['config']==cfg and x['case']==w['name']and x['variant']==v)for v in variants}
   summary[w['name']]={'median_ms':med,'ratios':{v:med[v]/med['baseline']for v in variants}}
  data['summaries'][cfg]=summary;save();print('measured',cfg,flush=True)
print('SCREEN COMPLETE',flush=True)

