#include <cstdint>
volatile std::uint64_t benchmark_salt = 1;
#include HEADER
#include <chrono>
#include <iostream>
#include <random>
#include <vector>
#include <cstdlib>
volatile std::uint64_t sink;
using Clock=std::chrono::steady_clock;
template<bool Packed,unsigned D> void run(std::size_t n,int family) {
 using Table=reinsirk::detail::InternalHashMap<std::uint64_t,std::uint64_t,Packed,D>;
 std::vector<std::uint64_t> keys(n);std::mt19937_64 rng(4372);
 for(std::size_t i=0;i<n;++i)keys[i]=family==0?rng():family==1?i:i*256;
 const int build_reps=n<=32?5000:n<=1024?100:1;
 const int find_reps=n<=32?10000:n<=1024?300:2;
 auto time=[&](const char* name,auto f,int reps){auto begin=Clock::now();std::uint64_t sum=0;for(int j=0;j<reps;++j)sum+=f();sink=sum;std::cout<<Packed<<':'<<D<<':'<<n<<':'<<family<<':'<<name<<' '<<std::chrono::duration<double,std::nano>(Clock::now()-begin).count()/reps<<' '<<sum<<'\n';};
 time("build",[&]{Table t;for(auto k:keys)t[k]=k+1;return t.size();},build_reps);
 time("reserve_build",[&]{Table t;t.reserve(n);for(auto k:keys)t[k]=k+1;return t.size();},build_reps);
 Table t;for(auto k:keys)t[k]=k+1;
 time("hit",[&]{std::uint64_t sum=0;for(auto k:keys){auto p=t.find(k);if(p)sum+=*p;}return sum;},find_reps);
 time("hit_subscript",[&]{std::uint64_t sum=0;for(auto k:keys)sum+=t[k];return sum;},find_reps);
 time("miss",[&]{std::uint64_t sum=0;for(auto k:keys)sum+=(t.find(k^UINT64_C(0xd6751cb79a3e5601))==nullptr);return sum;},find_reps);
 time("reuse",[&]{t.clear();for(auto k:keys)t[k]=k+1;return t.size();},build_reps);
}
int main(int argc,char**argv){benchmark_salt=argc>1?std::strtoull(argv[1],nullptr,0):1;for(auto n:{32U,1024U,200000U})for(int family:{0,1,2}){run<false,5>(n,family);if(family==0)run<true,4>(n,family);}run<false,5>(500000,0);}

