 for(std::size_t i=0;i<n;++i)keys[i]=family==0?rng():family==1?i:i*256;
 std::uint64_t sum=0;double ns=0;
 if(operation=="rehash"){
  for(int repeat=0;repeat<reps;++repeat){Table t;t.reserve(n);for(auto k:keys)t[k]=k+3;
   auto begin=Clock::now();t.reallocate();auto end=Clock::now();ns+=std::chrono::duration<double,std::nano>(end-begin).count();
   sum+=t.size();for(auto k:keys)sum+=*t.find(k);}
 }else if(operation=="build"){
  for(int repeat=0;repeat<reps;++repeat){auto begin=Clock::now();Table t;for(auto k:keys)t[k]=k+3;auto end=Clock::now();ns+=std::chrono::duration<double,std::nano>(end-begin).count();sum+=t.size();for(auto k:keys)sum+=*t.find(k);}

 }else{
  Table t;t.reserve(n);for(auto k:keys)t[k]=k+3;auto begin=Clock::now();
  for(int repeat=0;repeat<reps;++repeat)for(auto k:keys){if(operation=="hit")sum+=*t.find(k);else if(operation=="subscript")sum+=t[k];else sum+=t.find(k^UINT64_C(0x9e3779b97f4a7c15))==nullptr;}
  ns=std::chrono::duration<double,std::nano>(Clock::now()-begin).count();
 }
